    {
      "question_id": "Q1",
      "answered_aspects": [
        {
          "aspect_id": "Q1-A1",
          "claim": "虎㹠虎犢是王彭之與王彪之的小字，而非泛論比喻",
          "evidence": [
            { "ref": "L01", "quote": "虎㹠王彭之小字也" },
            { "ref": "L02", "quote": "虎犢彪之小字也" }
          ]
        }
      ],
      "unanswered_aspects": [],
      "conflicts": [],
      "reading_sufficient": true,
      "historical_verification_open": true
    },
    {
      "question_id": "Q2",
      "answered_aspects": [
        {
          "aspect_id": "Q2-A1",
          "claim": "『還其所如』意為恰如其小字，指王彭之、王彪之才質凡下，徒有虎名而實如豚犢",
          "evidence": [
            { "ref": "J02", "quote": "言彭之、彪之，生長高門，而才質凡下，羊質虎皮，恰如其名也。" },
            { "ref": "J02", "quote": "言彭之真豚犬之流，彪之初生之犢，二人之才正如其小字耳。" }
          ]
        }
      ],
      "unanswered_aspects": [],
      "conflicts": [],
      "reading_sufficient": true,
      "historical_verification_open": false
    },
    {
      "question_id": "Q3",
      "answered_aspects": [
        {
          "aspect_id": "Q3-A1",
          "claim": "程炎震推斷此事發生於王彪之初為郎時，王羲之身在江州，為通信語境提供了時間地點背景",
          "evidence": [
            { "ref": "J02", "quote": "程炎震云：「王導卒於咸康五年，彪之年三十四。此蓋彪之初為郎時，右軍當在江州。」" }
          ]
        }
      ],
      "unanswered_aspects": [
        {
          "aspect_id": "Q3-U1",
          "gap": "注文未說明王導與王右軍的具體宗族關係（如同宗叔姪），讀者無法確知王導為何向王羲之傾訴自家子姪不令",
          "reading_impact": "medium"
        },
        {
          "aspect_id": "Q3-U2",
          "gap": "注文未解釋王導嘆子姪不令、言『虎㹠虎犢還其所如』何以歸入『輕詆』篇，影響對篇目歸類意圖的理解",
          "reading_impact": "high"
        }
      ],
      "conflicts": [],
      "reading_sufficient": false,
      "historical_verification_open": true
    }
  ]
}

